#[inline]
pub unsafe fn xmlBufAdd(
    mut buf: xmlBufPtr,
    mut str: *const xmlChar,
    mut len: c_int,
) -> c_int {
    if str.is_null() || buf.is_null() || (*buf).error != 0 {
        return -(1 as c_int);
    }

    let b = &mut *buf;

    if b.size != b.compat_size as size_t && b.compat_size < INT_MAX as c_uint {
        b.size = b.compat_size as size_t;
    }
    if b.use_0 != b.compat_use as size_t && b.compat_use < INT_MAX as c_uint {
        b.use_0 = b.compat_use as size_t;
    }

    if len < -(1 as c_int) {
        return -(1 as c_int);
    }
    if len == 0 {
        return 0;
    }
    if len < 0 {
        len = xmlStrlen(str);
        if len < 0 {
            return -(1 as c_int);
        }
        if len == 0 {
            return 0;
        }
    }

    let len_usize = len as size_t;
    let use_0 = b.use_0;
    let size = b.size;

    if len_usize >= size.wrapping_sub(use_0) {
        if len_usize >= SIZE_MAX.wrapping_sub(use_0) {
            xmlBufMemoryError(
                buf,
                b"growing buffer past SIZE_MAX\0" as *const u8 as *const c_char,
            );
            return -(1 as c_int);
        }

        let need_size = use_0.wrapping_add(len_usize).wrapping_add(1 as size_t);

        if b.alloc as c_uint == XML_BUFFER_ALLOC_BOUNDED as c_int as c_uint
            && need_size >= XML_MAX_TEXT_LENGTH as size_t
        {
            xmlBufMemoryError(
                buf,
                b"buffer error: text too long\n\0" as *const u8 as *const c_char,
            );
            return -(1 as c_int);
        }

        if xmlBufResize(buf, need_size) == 0 {
            xmlBufMemoryError(
                buf,
                b"growing buffer\0" as *const u8 as *const c_char,
            );
            return XML_ERR_NO_MEMORY as c_int;
        }
    }

    // SAFETY: `buf` and `str` were validated non-null above; buffer capacity is ensured
    // by the resize logic, and `memmove` permits overlapping regions.
    memmove(
        b.content.add(b.use_0) as *mut c_void,
        str as *const c_void,
        len_usize,
    );

    let new_use = b.use_0.wrapping_add(len_usize);
    b.use_0 = new_use;
    // SAFETY: buffer has space for the trailing NUL because capacity was checked/resized
    // to hold `use_0 + len + 1`, and `content` points to that allocation.
    *b.content.add(new_use) = 0 as xmlChar;

    b.compat_size = if b.size < INT_MAX as size_t {
        b.size as c_uint
    } else {
        INT_MAX as c_uint
    };
    b.compat_use = if new_use < INT_MAX as size_t {
        new_use as c_uint
    } else {
        INT_MAX as c_uint
    };

    0
}

